"""Compile exact prepared sprites and approved walk frames; no artwork changes.

Requires Playwright Chromium. PNG bytes are generated by the existing renderer,
with unscaled putImageData copies. Runtime source metadata remains original.
"""
import base64,functools,hashlib,json
from pathlib import Path
from http.server import SimpleHTTPRequestHandler,ThreadingHTTPServer
from threading import Thread
from playwright.sync_api import sync_playwright
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'assets/cache'
class Quiet(SimpleHTTPRequestHandler):
 def log_message(self,*args):pass
server=ThreadingHTTPServer(('127.0.0.1',0),functools.partial(Quiet,directory=str(ROOT)));Thread(target=server.serve_forever,daemon=True).start()
try:
 with sync_playwright() as pw:
  browser=pw.chromium.launch(headless=True,args=['--no-sandbox']);page=browser.new_page();page.add_init_script('window.__BEARLY_BUILD_RENDER_CACHE=true');errors=[];page.on('pageerror',lambda e:errors.append(str(e)))
  npc=(ROOT/'js/npc-motion.js').read_text();kids=(ROOT/'js/illustrated-kids.js').read_text()
  npc=npc.replace('window.BearlyNpcMotion={','window.__exportNpc=()=>({profiles,walkBanks:[...walkBanks.values()]});window.BearlyNpcMotion={')
  kids=kids.replace('window.BearlyKids={','window.__exportKids=()=>({banks,sources});window.BearlyKids={')
  page.route('**/actor-cache-build.html',lambda r:r.fulfill(body='<script src="js/illustrated-kids.js"></script><script src="js/npc-motion.js"></script>',content_type='text/html'))
  page.route('**/js/npc-motion.js',lambda r:r.fulfill(body=npc,content_type='application/javascript'))
  page.route('**/js/illustrated-kids.js',lambda r:r.fulfill(body=kids,content_type='application/javascript'))
  page.goto(f'http://127.0.0.1:{server.server_port}/actor-cache-build.html');page.wait_for_function('BearlyKids.ready()&&BearlyNpcMotion.ready()',timeout=180000);page.evaluate('BearlyNpcMotion.preloadAll?.()');page.wait_for_function('BearlyNpcMotion.cacheStats().complete',timeout=180000)
  data=page.evaluate(r'''async()=>{
   const npc=__exportNpc(),kids=__exportKids(),outputs=[],hash=async data=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',data))).map(x=>x.toString(16).padStart(2,'0')).join('');
   const metadata=f=>Object.fromEntries(Object.entries(f).filter(([k])=>!['tile','feet','legSplit'].includes(k)));
   async function pack(name,frames){
    let x=0,y=0,rowH=0,maxX=0;const list=[];
    for(const f of frames){if(x+f.tile.width>2048){y+=rowH;x=0;rowH=0;}list.push({frame:f,cacheRect:[x,y,f.tile.width,f.tile.height]});x+=f.tile.width;maxX=Math.max(maxX,x);rowH=Math.max(rowH,f.tile.height);}
    const c=document.createElement('canvas');c.width=maxX;c.height=y+rowH;const g=c.getContext('2d'),result=[];
    for(const {frame,cacheRect}of list){const p=frame.tile.getContext('2d',{willReadFrequently:true}).getImageData(0,0,frame.tile.width,frame.tile.height);g.putImageData(p,cacheRect[0],cacheRect[1]);result.push({...metadata(frame),cacheRect,pixelSHA256:await hash(p.data)});}
    outputs.push({name,data:c.toDataURL('image/png')});return{file:'assets/cache/'+name,width:c.width,height:c.height,frames:result};
   }
   const groups=new Map();for(const p of npc.profiles)for(const f of Object.values(p.poses)){const name=f.source.split('/').pop();if(!groups.has(name))groups.set(name,[]);groups.get(name).push(f);}
   const npcSources=[];let index=0;for(const [source,frames]of groups)npcSources.push({source,...await pack('npc-source-'+index+++'-v19.png',frames)});
   const teenSources=[];index=0;for(const [source,entry]of Object.entries(kids.sources))teenSources.push({source,rows:entry.rows,cols:entry.cols,components:entry.components,...await pack('teen-source-'+index+++'-v19.png',entry.frames)});
   const kidsBanks=Object.fromEntries(Object.entries(kids.banks).map(([kind,bank])=>[kind,{stature:bank.stature,frames:Object.fromEntries(Object.entries(bank.frames).map(([pose,f])=>[pose,metadata(f)]))}]));
   const walks=[];for(const bank of npc.walkBanks){const c=document.createElement('canvas');c.width=bank.width*8;c.height=bank.height*6;const g=c.getContext('2d'),frames=[];
    for(let i=0;i<48;i++){const f=bank.frames[i],tile=document.createElement('canvas');tile.width=bank.width;tile.height=bank.height;const t=tile.getContext('2d',{willReadFrequently:true});t.drawImage(f.canvas,0,0);const p=t.getImageData(0,0,tile.width,tile.height);g.putImageData(p,(i%8)*bank.width,Math.floor(i/8)*bank.height);frames.push({index:i,details:f.details,pixelSHA256:await hash(p.data)});}
    const name='npc-walk-'+bank.variant+'-v19.png';outputs.push({name,data:c.toDataURL('image/png')});walks.push({variant:bank.variant,file:'assets/cache/'+name,width:bank.width,height:bank.height,x:bank.x,y:bank.y,columns:8,frames});
   }
   return{manifest:{format:1,version:'v19',npcSources,teenSources,kidsBanks,walks},outputs};
  }''')
  assert not errors,errors
  OUT.mkdir(exist_ok=True)
  for item in data['outputs']:(OUT/item['name']).write_bytes(base64.b64decode(item['data'].split(',',1)[1]))
  manifest=data['manifest'];sources={f['source'] for f in [*manifest['npcSources'],*manifest['teenSources']]};manifest['sourceSHA256']={f'assets/art/{name}':hashlib.sha256((ROOT/'assets/art'/name).read_bytes()).hexdigest() for name in sorted(sources)}
  manifest['cacheSHA256']={item['name']:hashlib.sha256((OUT/item['name']).read_bytes()).hexdigest() for item in data['outputs']}
  manifest['rendererSHA256']={name:hashlib.sha256((ROOT/name).read_bytes()).hexdigest() for name in ['js/npc-motion.js','js/illustrated-kids.js']}
  (OUT/'actors-v19-manifest.json').write_text(json.dumps(manifest,separators=(',',':'))+'\n')
  print(json.dumps({'files':len(data['outputs']),'bytes':sum((OUT/x['name']).stat().st_size for x in data['outputs']),'npcFrames':sum(len(x['frames'])for x in manifest['npcSources']),'teenFrames':sum(len(x['frames'])for x in manifest['teenSources']),'walkFrames':sum(len(x['frames'])for x in manifest['walks'])}))
  browser.close()
finally:server.shutdown()
